// Runs the UC-001 roster import once per day at midnight without adding a
// cron dependency. The slot set prevents repeated imports during midnight.
const rosterSyncService = require("../services/rosterSyncService");

const CHECK_INTERVAL_MS = 60 * 1000;
const completedDates = new Set();

function runIfDue(now = new Date()) {
  if (now.getHours() !== 0 || now.getMinutes() !== 0) return;

  const dateKey = now.toISOString().slice(0, 10);
  if (completedDates.has(dateKey)) return;

  completedDates.add(dateKey);
  rosterSyncService.runRosterSync(undefined, "scheduler").catch((error) => {
    console.error("[rosterSyncScheduler] Scheduled sync failed:", error.message);
  });
}

function start() {
  setInterval(() => runIfDue(), CHECK_INTERVAL_MS);
}

module.exports = { start, runIfDue };
const { parse } = require("csv-parse/sync");

// Fetches the published roster CSV and returns an array of row objects.
// Each row looks like: { "Staff ID": "S001", "Staff Name": "Andrea Chua", "Date": "2026-07-01", "Clock In": "08:00", "Clock Out": "17:00" }
async function fetchRosterRows() {
  const url = process.env.ROSTER_SHEET_CSV_URL;

  if (!url) {
    throw new Error("ROSTER_SHEET_CSV_URL is not set in .env");
  }

  const response = await fetch(url);

  if (!response.ok) {
    throw new Error(`Failed to fetch roster sheet: ${response.status} ${response.statusText}`);
  }

  const csvText = await response.text();

  const rows = parse(csvText, {
    columns: true,       // use first row as headers
    skip_empty_lines: true,
    trim: true,
  });

  return rows;
}

module.exports = { fetchRosterRows };
const { AuditLog } = require("../models");

const safeDetails = (details = {}) => {
  const blockedKeys = new Set([
    "password",
    "passwordHash",
    "password_hash",
    "token",
    "jwt",
    "bank_account_no",
  ]);

  return Object.fromEntries(
    Object.entries(details || {}).filter(([key]) => !blockedKeys.has(key))
  );
};

