import { useEffect, useState } from "react";
import { fetchPayPeriods } from "../api/payPeriods";
import "../styles/rosterSync.css";

function PayPeriodsPage() {
  const [periods, setPeriods] = useState([]);
  const [loading, setLoading] = useState(true);
  const [errorMessage, setErrorMessage] = useState("");

  useEffect(() => {
    fetchPayPeriods()
      .then((data) => setPeriods(data))
      .catch((error) => setErrorMessage(error.message))
      .finally(() => setLoading(false));
  }, []);

  return (
    <main className="roster-page">
      <header className="roster-intro"><h1>Pay Periods</h1><p>View the automatically generated payroll periods.</p></header>
      {errorMessage && <p className="roster-banner roster-error">{errorMessage}</p>}
      <section className="roster-card">
        <h2>All Pay Periods</h2>
        {loading && <p className="roster-empty">Loading pay periods...</p>}
        {!loading && periods.length === 0 && <p className="roster-empty">No pay periods found.</p>}
        {!loading && periods.length > 0 && <div className="roster-table-scroll"><table><thead><tr><th>Start date</th><th>End date</th><th>Status</th></tr></thead><tbody>{periods.map((period) => <tr key={period.id}><td>{period.startDate}</td><td>{period.endDate}</td><td>{period.isActive ? "Active" : "Inactive"}</td></tr>)}</tbody></table></div>}
      </section>
    </main>
  );
}

export default PayPeriodsPage;

