// UC-001: Turns a "clock in" / "clock out" time into a number of hours.
// Times are simple 24-hour strings like "08:00" or "17:30".

function timeStringToMinutes(timeString) {
  if (typeof timeString !== "string" || !/^([01]\d|2[0-3]):[0-5]\d$/.test(timeString)) {
    return Number.NaN;
  }

  const [hours, minutes] = timeString.split(":").map(Number);
  return hours * 60 + minutes;
}

function calculateHours(clockIn, clockOut) {
  let minutesWorked = timeStringToMinutes(clockOut) - timeStringToMinutes(clockIn);

  // Negative means the shift crossed midnight (e.g. 22:00 -> 06:00) â€” add a day.
  if (minutesWorked < 0) {
    minutesWorked += 24 * 60;
  }

  const hoursWorked = minutesWorked / 60;

  // Round to 2 decimal places so totals look clean (e.g. 8.5, not 8.500000001).
  return Math.round(hoursWorked * 100) / 100;
}

module.exports = { calculateHours };
const { AuditLog } = require("../models");

const safeDetails = (details = {}) => {
  const blockedKeys = new Set([
    "password",
    "passwordHash",
    "password_hash",
    "token",
    "jwt",
    "bank_account_no",
  ]);

  return Object.fromEntries(
    Object.entries(details || {}).filter(([key]) => !blockedKeys.has(key))
  );
};

// ==========================================================
// UC-005 / shared audit API
// ==========================================================

const record = async ({
  user = null,
  action,
  entityType,
  entityId = null,
  ipAddress = null,
  details = {},
}) =>
  AuditLog.create({
    user_id: user?.id || null,
    user_role: user?.role || null,
    action,
    entity_type: entityType,
    entity_id: entityId,
    actor: user?.email || "anonymous",
    ip_address: ipAddress,
    details: safeDetails(details),
  });

// ==========================================================
// Compatibility API used by UC-001
// ==========================================================

const logAction = async ({
  entityType,
  entityId,
  action,
  actor,
  detail,
}) =>
  AuditLog.create({
    user_id: null,
    user_role: null,
    action,
    entity_type: entityType,
    entity_id: entityId,
    actor: actor || "system",
    ip_address: null,
    details: safeDetails(detail || {}),
  });

const getHistory = async (entityType, entityId, limit = 10) => {
  const rows = await AuditLog.findAll({
    where: {
      entity_type: entityType,
      entity_id: entityId,
    },
    order: [["created_at", "DESC"]],
    limit,
  });

  return rows.map((row) => {
    const values = row.get({ plain: true });

    return {
      action: values.action,
      actor: values.actor,
      detail: values.details,
      createdAt: values.created_at || values.createdAt,
    };
  });
};

module.exports = {
  record,
  logAction,
  getHistory,
};

